insert into projects (team_id,name) values ('10000000-0000-0000-0000-000000000001','nope');
update projects set name='x' returning *; delete from projects returning *;
delete from team_members where user_id=:'A' returning *;
insert into team_members values ('10000000-0000-0000-0000-000000000001',:'B','admin');
update team_members set role='admin' where user_id=:'B' returning *;
reset role;
\echo === admin A: write own team
set role authenticated; set request.jwt.claim.sub = :'A';
insert into projects (team_id,name) values ('10000000-0000-0000-0000-000000000001','new') returning name, created_by;
update projects set name='P1b' where name='P1' returning name;
\echo -- move to T2 should fail
update projects set team_id='10000000-0000-0000-0000-000000000002' where name='P1b';
\echo -- insert into T2 should fail
insert into projects (team_id,name) values ('10000000-0000-0000-0000-000000000002','x');
\echo -- add self to T2 should fail
insert into team_members values ('10000000-0000-0000-0000-000000000002',:'A','admin');
\echo -- C's project invisible / undeletable: expect 0
delete from projects where name='P2' returning *;
select count(*) from team_members where team_id='10000000-0000-0000-0000-000000000002';
insert into team_members values ('10000000-0000-0000-0000-000000000001',:'C','member') returning *;
delete from team_members where user_id=:'C' returning *;
delete from projects where name='new' returning name;
\echo -- rpc into private fn as anon
reset role; set role anon; select private.is_team_member('10000000-0000-0000-0000-000000000001');
EOF
docker run -d --rm --name rlstest -e POSTGRES_PASSWORD=x postgres:15 >/dev/null && until docker exec rlstest pg_isready -U postgres >/dev/null 2>&1; do sleep 1; done; sleep 2
for f in $T/00_stub.sql supabase/migrations/20260101000000_init.sql $T/03_grants.sql supabase/migrations/20261022000000_enable_rls.sql; do docker exec -i rlstest psql -q -v ON_ERROR_STOP=1 -U postgres < $f || echo "FAILED $f"; done
